CREATE TABLE "research_profiles" (
  "key" text,
  "cap_ms" bigint,
  "synthesis_reserve_ms" bigint,
  "effort" text,
  "child_role" text NOT NULL,
  "max_children" bigint NOT NULL,
  "wait_limit_ms" bigint NOT NULL,
  "strategy" text NOT NULL,
  "host_interval_ms" bigint NOT NULL,
  "engine_interval_ms" bigint NOT NULL,
  "set_at" bigint NOT NULL,
  "rowid" bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("key")
);
